fn most_frequent(xs: List[Int]) -> Option[Int]
  requires len(xs) == 0 or exists x in xs: forall y in xs: (y == x) or (count(xs, y) < count(xs, x))
  ensures is_mode(xs, result)
  effects pure
  example most_frequent([]) == None
  example most_frequent([1]) == Some(1)
  example most_frequent([1, 2, 2, 3]) == Some(2)
  example most_frequent([5, 5, 5, 1, 1]) == Some(5)
{
  match xs {
    [] => None
    [h, ..t] => Some(find_max_by_count(xs, h, xs))
  }
}

fn find_max_by_count(xs: List[Int], current_max: Int, remaining: List[Int]) -> Int
  requires contains(xs, current_max) and forall r in remaining: contains(xs, r) and (exists x in xs: forall y in xs: (y == x) or (count(xs, y) < count(xs, x)))
  ensures contains(xs, result) and forall y in xs: (y == result or count(xs, y) < count(xs, result))
  effects pure
  example find_max_by_count([1, 2, 2, 3], 1, [1, 2, 2, 3]) == 2
  example find_max_by_count([5, 5, 5, 1, 1], 5, [5, 5, 5, 1, 1]) == 5
{
  match remaining {
    [] => current_max
    [h, ..t] =>
      if count(xs, h) > count(xs, current_max)
        then find_max_by_count(xs, h, t)
        else find_max_by_count(xs, current_max, t)
  }
}

